const Post = require('../models/Post');
const mongoose = require('mongoose');

// GET /api/posts?limit=10&page=1&author=Alice&q=keyword
exports.listPosts = async (req, res, next) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const page = Math.max(parseInt(req.query.page) || 1, 1);
    const skip = (page - 1) * limit;

    const filter = {};
    if (req.query.author) filter.author = req.query.author;
    if (req.query.q) filter.$or = [
      { title: new RegExp(req.query.q, 'i') },
      { text: new RegExp(req.query.q, 'i') }
    ];

    const [items, total] = await Promise.all([
      Post.find(filter).sort({ createdAt: -1 }).skip(skip).limit(limit).select('title text author createdAt'),
      Post.countDocuments(filter)
    ]);

    res.json({
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
      items
    });
  } catch (err) { next(err); }
};

exports.getPost = async (req, res, next) => {
  try {
    const id = req.params.id;
    if (!mongoose.isValidObjectId(id)) return res.status(400).json({ error: 'Invalid id' });

    const post = await Post.findById(id).select('title text author createdAt');
    if (!post) return res.status(404).json({ error: 'Not found' });
    res.json(post);
  } catch (err) { next(err); }
};

exports.createPost = async (req, res, next) => {
  try {
    const { title, text, author } = req.body;
    if (!title || !text || !author) return res.status(400).json({ error: 'title, text and author required' });

    const post = new Post({ title, text, author });
    await post.save();
    res.status(201).json(post);
  } catch (err) { next(err); }
};
```

